<th>默认值</th>
</tr>
</thead>
<tbody>
<tr>
<td>model-value(<strong>v-model</strong>)</td>
<td>绑定值｜<code v-pre>string</code></td>
<td><code v-pre>-</code></td>
<td></td>
</tr>
<tr>
<td>default-value</td>
<td>默认值(非受控状态)</td>
<td><code v-pre>string</code></td>
<td><code v-pre>''</code></td>
</tr>
<tr>
<td>placeholder</td>
<td>提示文字</td>
<td><code v-pre>string</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>disabled</td>
<td>是否禁用</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>error</td>
<td>是否为错误状态</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>max-length</td>
<td>输入的最大长度</td>
<td><code v-pre>number|{length:number,errorOnly?:boolean</code></td>
<td><code v-pre>0</code></td>
</tr>
<tr>
<td>show-word-limit</td>
<td>是否显示字数统计</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>clearable</td>
<td>是否允许清空文本域</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>auto-size</td>
<td>是否让文本自适应内容高度</td>
<td><code v-pre>boolean|{minRows?;number,maxRows?;number</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>word-length</td>
<td>字符长度的计算方法</td>
<td><code v-pre>(value:string)=&gt;number</code></td>
<td><code v-pre>-</code></td>
</tr>
<tr>
<td>word-slice</td>
